from app.core.metrics.prometheus import prometheus

presigned_urls_generated_total = prometheus.register_counter(
    "storage_presigned_urls_generated_total",
    "Total presigned URLs generated by the object storage backend",
    ["operation"],
)

storage_object_deletes_total = prometheus.register_counter(
    "storage_object_deletes_total",
    "Total object delete operations performed against the object storage backend",
)
